import attributeNamesData from "./generated/attribute-names.json";

/**
 * Each tag's attribute names, as the schema lists them (aliases included),
 * without the rest of the schema. Generated by `scripts/generate-schema.ts`.
 * The parser reads it to give an attribute written in another case its
 * component's spelling (D51), in code the viewer loads eagerly, where the
 * whole schema would be hundreds of kB.
 */
const data = attributeNamesData as {
    names: string[];
    tags: Record<string, number[]>;
};

const cache = new Map<string, string[]>();

/** The attribute names the schema lists for `tag`, or `undefined` if it lists no such tag. */
export function attributeNamesOfTag(tag: string): string[] | undefined {
    if (!Object.prototype.hasOwnProperty.call(data.tags, tag)) {
        return undefined;
    }
    let names = cache.get(tag);
    if (names === undefined) {
        names = data.tags[tag].map((index) => data.names[index]);
        cache.set(tag, names);
    }
    return names;
}
